// balance e amount_spent vêm em centavos.
const cent = v => v == null ? null : Number(v) / 100;
const rows = [];
for (const item of $input.all()) {
  for (const o of Object.values(item.json)) {
    if (!o || typeof o !== 'object' || !o.account_id) continue;
    rows.push({
      conta_id: String(o.account_id),
      nome_conta: o.name ?? null,
      moeda: o.currency ?? null,
      saldo: cent(o.balance),
      spend_cap: cent(o.spend_cap),
      amount_spent: cent(o.amount_spent),
      status_conta: o.account_status ?? null,
      fonte_pagamento: o.funding_source_details?.type != null ? String(o.funding_source_details.type) : null,
      funding_display: o.funding_source_details?.display_string ?? null,
      limite_restante: (o.spend_cap && Number(o.spend_cap) > 0)
        ? cent(Number(o.spend_cap) - Number(o.amount_spent ?? 0))
        : null,
      timezone_name: o.timezone_name ?? null,
      tz_offset_utc: o.timezone_offset_hours_utc ?? null,
    });
  }
}
return [{ json: { linhas: rows.length, payload: JSON.stringify(rows) } }];

